local FILES = {
{"ReplicatedStorage/Shared/Config/BuildingConfig","ModuleScript","--!strict\n-- BuildingConfig (ModuleScript). The ten business stages. Costs are initial balancing targets.\n-- `Implemented` marks stages that have a built model/mechanics yet (MVP = stages 1-3).\n\nexport type Stage = {\n\tLevel: number,\n\tId: string,\n\tName: string,\n\tCost: number,\n\tShelfSlots: number,\n\tEmployeeSlots: number,\n\tCustomerCap: number, -- max simultaneous customer NPCs\n\tFeatures: { string }, -- new mechanics unlocked at this stage\n\tImplemented: boolean,\n}\n\nlocal STAGES: { Stage } = {\n\t{ Level = 1, Id = \"roadside_tent\", Name = \"Roadside Tent\", Cost = 0, ShelfSlots = 1, EmployeeSlots = 0, CustomerCap = 2, Features = { \"Manual checkout\", \"Starter launch pad\" }, Implemented = true },\n\t{ Level = 2, Id = \"upgraded_stand\", Name = \"Upgraded Stand\", Cost = 500, ShelfSlots = 2, EmployeeSlots = 1, CustomerCap = 3, Features = { \"Second shelf\", \"First employee slot\" }, Implemented = false },\n\t{ Level = 3, Id = \"firework_shack\", Name = \"Firework Shack\", Cost = 2500, ShelfSlots = 4, EmployeeSlots = 2, CustomerCap = 4, Features = { \"Regional Distributor\", \"Faster delivery truck\", \"Rare fireworks\" }, Implemented = false },\n\t{ Level = 4, Id = \"small_store\", Name = \"Small Firework Store\", Cost = 10000, ShelfSlots = 6, EmployeeSlots = 3, CustomerCap = 6, Features = { \"Premium Imports\", \"Shelf stockers\" }, Implemented = false },\n\t{ Level = 5, Id = \"outlet\", Name = \"Firework Outlet\", Cost = 50000, ShelfSlots = 8, EmployeeSlots = 4, CustomerCap = 8, Features = { \"Firework show creator\", \"Multiple simultaneous orders\" }, Implemented = false },\n\t{ Level = 6, Id = \"superstore\", Name = \"Firework Superstore\", Cost = 250000, ShelfSlots = 12, EmployeeSlots = 6, CustomerCap = 10, Features = { \"Elite Fireworks\", \"Self-checkout stations\" }, Implemented = false },\n\t{ Level = 7, Id = \"warehouse\", Name = \"Firework Warehouse\", Cost = 1000000, ShelfSlots = 16, EmployeeSlots = 8, CustomerCap = 12, Features = { \"Warehouse storage\", \"Pallet racks\" }, Implemented = false },\n\t{ Level = 8, Id = \"distribution_center\", Name = \"Firework Distribution Center\", Cost = 5000000, ShelfSlots = 20, EmployeeSlots = 10, CustomerCap = 14, Features = { \"Galactic Supplier\", \"Automatic unloading\" }, Implemented = false },\n\t{ Level = 9, Id = \"megastore\", Name = \"Firework Megastore\", Cost = 25000000, ShelfSlots = 28, EmployeeSlots = 12, CustomerCap = 16, Features = { \"Legendary display cases\", \"Bulk orders\" }, Implemented = false },\n\t{ Level = 10, Id = \"empire\", Name = \"Firework Empire\", Cost = 100000000, ShelfSlots = 36, EmployeeSlots = 16, CustomerCap = 20, Features = { \"Prestige unlocked\" }, Implemented = false },\n}\n\nlocal BuildingConfig = {}\n\nBuildingConfig.Stages = STAGES\nBuildingConfig.MaxStage = #STAGES\nBuildingConfig.PlotSize = 70 -- studs; must match MapBuilder\n\nfunction BuildingConfig.Get(level: number): Stage\n\treturn STAGES[math.clamp(math.floor(level), 1, #STAGES)]\nend\n\nfunction BuildingConfig.Next(level: number): Stage?\n\treturn STAGES[level + 1]\nend\n\nreturn BuildingConfig\n"},
{"ReplicatedStorage/Shared/Config/EconomyConfig","ModuleScript","--!strict\n-- EconomyConfig (ModuleScript). Global economy numbers. Everything here is a tuning knob.\n\nlocal EconomyConfig = {}\n\nEconomyConfig.StartingCash = 100\nEconomyConfig.MaxCash = 1e15 -- hard sanity cap so numbers never overflow display or storage\n\n-- Player XP level curve: XP needed to go from `level` to `level + 1`.\nEconomyConfig.XP = {\n\tBase = 40,\n\tExponent = 1.55,\n\tMaxLevel = 100,\n}\n\nfunction EconomyConfig.XPToNextLevel(level: number): number\n\treturn math.floor(EconomyConfig.XP.Base * (math.max(level, 1) ^ EconomyConfig.XP.Exponent))\nend\n\n-- Pacing targets from the design spec (seconds). Used by the Phase 8 balancing tools and analytics checks.\nEconomyConfig.PacingTargets = {\n\tFirstSale = 60,\n\tFirstLaunch = 120,\n\tFirstUpgrade = { 180, 300 },\n\tFirstEmployee = { 600, 900 },\n\tFirstRareFirework = { 600, 1200 },\n\tFirstMajorExpansion = { 1200, 2400 },\n}\n\nEconomyConfig.OfflineEarningsCapSeconds = 8 * 60 * 60\n\nEconomyConfig.SupplierRestockSeconds = 300\n\nreturn EconomyConfig\n"},
{"ReplicatedStorage/Shared/Config/FireworkConfig","ModuleScript","--!strict\n-- FireworkConfig (ModuleScript). Single source of truth for every sellable firework.\n--\n-- ADDING CONTENT WITHOUT EDITING THIS FILE:\n--   Put a ModuleScript *inside* this ModuleScript that returns an array of FireworkDef tables\n--   (use the same field names as below). They are registered automatically on require.\n--\n-- Collection status (discovered / purchased / launched) is PLAYER state, stored in PlayerData.Collection.\n-- `Effect` is only an id here; Phase 3's FireworkEffects module owns the visuals for each id.\n\nlocal Types = require(script.Parent.Parent.Types)\nlocal RarityConfig = require(script.Parent.RarityConfig)\n\nlocal FireworkConfig = {}\n\n-- fw(id, name, description, rarity, wholesale, retail, stockMin, stockMax, supplier, unlockStage, demand, xp)\nlocal function fw(\n\tid: string,\n\tname: string,\n\tdesc: string,\n\trarity: Types.Rarity,\n\tcost: number,\n\tretail: number,\n\tstockMin: number,\n\tstockMax: number,\n\tsupplier: string,\n\tunlock: number,\n\tdemand: number,\n\txp: number\n): Types.FireworkDef\n\treturn {\n\t\tId = id,\n\t\tDisplayName = name,\n\t\tDescription = desc,\n\t\tRarity = rarity,\n\t\tWholesaleCost = cost,\n\t\tRetailPrice = retail,\n\t\tSupplierStock = { Min = stockMin, Max = stockMax },\n\t\tSupplier = supplier,\n\t\tUnlockLevel = unlock,\n\t\tDemand = demand,\n\t\tModel = id,\n\t\tEffect = id,\n\t\tXPReward = xp,\n\t}\nend\n\nlocal LW, RD, PI, EF, GS = \"LocalWholesale\", \"RegionalDistributor\", \"PremiumImports\", \"EliteFireworks\", \"GalacticSupplier\"\n\nlocal BASE: { Types.FireworkDef } = {\n\t-- Common\n\tfw(\"tiny_spark\", \"Tiny Spark\", \"A cheerful little fizz of silver sparks.\", \"Common\", 5, 9, 40, 80, LW, 1, 1.0, 3),\n\tfw(\"candy_crackle\", \"Candy Crackle\", \"Pastel pops that crackle like sugar.\", \"Common\", 8, 15, 30, 60, LW, 1, 1.0, 4),\n\tfw(\"golden_fountain\", \"Golden Fountain\", \"A warm fountain of golden glitter.\", \"Common\", 12, 22, 30, 60, LW, 1, 1.0, 5),\n\tfw(\"rainbow_pop\", \"Rainbow Pop\", \"Seven colours, one happy bang.\", \"Common\", 20, 36, 25, 50, LW, 2, 0.95, 6),\n\t-- Uncommon\n\tfw(\"thunder_burst\", \"Thunder Burst\", \"A booming blue-white burst.\", \"Uncommon\", 40, 72, 15, 35, LW, 2, 0.9, 12),\n\tfw(\"starlight_twirl\", \"Starlight Twirl\", \"Stars spiral up and twinkle out.\", \"Uncommon\", 55, 100, 12, 30, LW, 2, 0.9, 14),\n\tfw(\"neon_dragon\", \"Neon Dragon\", \"A glowing dragon coils across the sky.\", \"Uncommon\", 75, 135, 10, 25, LW, 3, 0.85, 16),\n\t-- Rare\n\tfw(\"heartbeat_bloom\", \"Heartbeat Bloom\", \"Pulsing pink hearts in the dark.\", \"Rare\", 200, 380, 6, 14, RD, 3, 0.75, 38),\n\tfw(\"galaxy_bloom\", \"Galaxy Bloom\", \"A spinning galaxy of violet and gold.\", \"Rare\", 150, 285, 6, 16, RD, 3, 0.75, 30),\n\tfw(\"solar_storm\", \"Solar Storm\", \"Fiery rings roll out like a sun flare.\", \"Rare\", 300, 570, 5, 12, RD, 4, 0.7, 50),\n\t-- Epic\n\tfw(\"phantom_sky\", \"Phantom Sky\", \"Ghostly lights drift and fade.\", \"Epic\", 750, 1500, 3, 8, PI, 4, 0.55, 100),\n\tfw(\"aurora_cascade\", \"Aurora Cascade\", \"Curtains of green and violet fall slowly.\", \"Epic\", 1100, 2200, 2, 7, PI, 5, 0.55, 125),\n\tfw(\"midnight_dragon\", \"Midnight Dragon\", \"A huge shadow dragon breathes silver fire.\", \"Epic\", 1500, 3000, 2, 6, PI, 5, 0.5, 160),\n\t-- Legendary\n\tfw(\"celestial_crown\", \"Celestial Crown\", \"A royal crown of light above the crowd.\", \"Legendary\", 5000, 11000, 1, 4, EF, 6, 0.35, 400),\n\tfw(\"golden_waterfall\", \"Golden Waterfall\", \"A thundering cascade of liquid gold.\", \"Legendary\", 8000, 17500, 1, 3, EF, 7, 0.3, 550),\n\t-- Mythical\n\tfw(\"supernova\", \"Supernova\", \"The sky erupts in a star-sized flash.\", \"Mythical\", 25000, 60000, 1, 2, GS, 8, 0.2, 1500),\n\tfw(\"planet_parade\", \"Planet Parade\", \"Ringed planets march across the horizon.\", \"Mythical\", 40000, 95000, 1, 2, GS, 9, 0.18, 2000),\n\t-- Secret\n\tfw(\"cosmic_apocalypse\", \"Cosmic Apocalypse\", \"Nobody is sure what it does. Everybody watches.\", \"Secret\", 100000, 250000, 1, 1, GS, 10, 0.1, 6000),\n}\n\nlocal registry: { [string]: Types.FireworkDef } = {}\nlocal ordered: { Types.FireworkDef } = {}\n\nlocal function validate(def: any): string?\n\tif type(def) ~= \"table\" then\n\t\treturn \"entry is not a table\"\n\tend\n\tif type(def.Id) ~= \"string\" or def.Id == \"\" then\n\t\treturn \"missing Id\"\n\tend\n\tif registry[def.Id] then\n\t\treturn \"duplicate Id \" .. def.Id\n\tend\n\tif type(def.DisplayName) ~= \"string\" then\n\t\treturn \"missing DisplayName\"\n\tend\n\tif type(def.Rarity) ~= \"string\" or not RarityConfig.IsValid(def.Rarity) then\n\t\treturn \"invalid Rarity\"\n\tend\n\tif type(def.WholesaleCost) ~= \"number\" or def.WholesaleCost <= 0 then\n\t\treturn \"invalid WholesaleCost\"\n\tend\n\tif type(def.RetailPrice) ~= \"number\" or def.RetailPrice <= def.WholesaleCost then\n\t\treturn \"RetailPrice must be greater than WholesaleCost\"\n\tend\n\tif type(def.SupplierStock) ~= \"table\" or type(def.SupplierStock.Min) ~= \"number\" or type(def.SupplierStock.Max) ~= \"number\" then\n\t\treturn \"invalid SupplierStock\"\n\tend\n\treturn nil\nend\n\nlocal function register(def: any, source: string)\n\tlocal problem = validate(def)\n\tif problem then\n\t\twarn((\"[FireworkConfig] Skipped entry from %s: %s\"):format(source, problem))\n\t\treturn\n\tend\n\tregistry[def.Id] = def\n\ttable.insert(ordered, def)\nend\n\nfor _, def in BASE do\n\tregister(def, \"FireworkConfig\")\nend\n\n-- Auto-register content packs placed as child ModuleScripts.\nfor _, child in script:GetChildren() do\n\tif child:IsA(\"ModuleScript\") then\n\t\tlocal ok, pack = pcall(require, child)\n\t\tif ok and type(pack) == \"table\" then\n\t\t\tfor _, def in pack do\n\t\t\t\tregister(def, child.Name)\n\t\t\tend\n\t\telse\n\t\t\twarn(\"[FireworkConfig] Could not load content pack \" .. child.Name)\n\t\tend\n\tend\nend\n\ntable.sort(ordered, function(a, b)\n\tlocal ra, rb = RarityConfig.GetRank(a.Rarity), RarityConfig.GetRank(b.Rarity)\n\tif ra ~= rb then\n\t\treturn ra < rb\n\tend\n\treturn a.WholesaleCost < b.WholesaleCost\nend)\n\nfunction FireworkConfig.Get(id: string): Types.FireworkDef?\n\treturn registry[id]\nend\n\nfunction FireworkConfig.GetAll(): { Types.FireworkDef }\n\treturn ordered\nend\n\nfunction FireworkConfig.Count(): number\n\treturn #ordered\nend\n\nfunction FireworkConfig.GetByRarity(rarity: Types.Rarity): { Types.FireworkDef }\n\tlocal list = {}\n\tfor _, def in ordered do\n\t\tif def.Rarity == rarity then\n\t\t\ttable.insert(list, def)\n\t\tend\n\tend\n\treturn list\nend\n\nfunction FireworkConfig.GetBySupplier(supplierId: string): { Types.FireworkDef }\n\tlocal list = {}\n\tfor _, def in ordered do\n\t\tif def.Supplier == supplierId then\n\t\t\ttable.insert(list, def)\n\t\tend\n\tend\n\treturn list\nend\n\nreturn FireworkConfig\n"},
{"ReplicatedStorage/Shared/Config/RarityConfig","ModuleScript","--!strict\n-- RarityConfig (ModuleScript). Colours + supplier appearance weights. Tune weights after playtesting.\n\nlocal Types = require(script.Parent.Parent.Types)\n\ntype RarityInfo = {\n\tRank: number,\n\tColor: Color3,\n\tWeight: number, -- percent chance for a supplier slot (relative weights; need not sum to 100)\n\tAnimated: boolean?,\n}\n\nlocal RarityConfig = {}\n\nRarityConfig.Order = { \"Common\", \"Uncommon\", \"Rare\", \"Epic\", \"Legendary\", \"Mythical\", \"Secret\" } :: { Types.Rarity }\n\nRarityConfig.Info = {\n\tCommon = { Rank = 1, Color = Color3.fromRGB(160, 160, 168), Weight = 45 },\n\tUncommon = { Rank = 2, Color = Color3.fromRGB(86, 204, 100), Weight = 27 },\n\tRare = { Rank = 3, Color = Color3.fromRGB(64, 140, 255), Weight = 16 },\n\tEpic = { Rank = 4, Color = Color3.fromRGB(165, 82, 235), Weight = 8 },\n\tLegendary = { Rank = 5, Color = Color3.fromRGB(255, 196, 40), Weight = 3 },\n\tMythical = { Rank = 6, Color = Color3.fromRGB(235, 55, 60), Weight = 0.9 },\n\tSecret = { Rank = 7, Color = Color3.fromRGB(255, 255, 255), Weight = 0.1, Animated = true },\n} :: { [string]: RarityInfo }\n\nfunction RarityConfig.IsValid(rarity: string): boolean\n\treturn RarityConfig.Info[rarity] ~= nil\nend\n\nfunction RarityConfig.GetRank(rarity: string): number\n\tlocal info = RarityConfig.Info[rarity]\n\treturn if info then info.Rank else 0\nend\n\n-- Pass os.clock() as `t` so the Secret rarity cycles through the rainbow.\nfunction RarityConfig.GetColor(rarity: string, t: number?): Color3\n\tlocal info = RarityConfig.Info[rarity]\n\tif not info then\n\t\treturn Color3.new(1, 1, 1)\n\tend\n\tif info.Animated then\n\t\treturn Color3.fromHSV(((t or 0) * 0.25) % 1, 0.75, 1)\n\tend\n\treturn info.Color\nend\n\n-- Weighted pick used by the supplier (Phase 2). `rng` is a Random object.\nfunction RarityConfig.Roll(rng: Random, allowed: { [string]: boolean }?): Types.Rarity\n\tlocal total = 0\n\tfor _, name in RarityConfig.Order do\n\t\tif not allowed or allowed[name] then\n\t\t\ttotal += RarityConfig.Info[name].Weight\n\t\tend\n\tend\n\tlocal pick = rng:NextNumber() * total\n\tfor _, name in RarityConfig.Order do\n\t\tif not allowed or allowed[name] then\n\t\t\tpick -= RarityConfig.Info[name].Weight\n\t\t\tif pick <= 0 then\n\t\t\t\treturn name\n\t\t\tend\n\t\tend\n\tend\n\treturn \"Common\"\nend\n\nreturn RarityConfig\n"},
{"ReplicatedStorage/Shared/Config/SupplierConfig","ModuleScript","--!strict\n-- SupplierConfig (ModuleScript). Added to the suggested architecture so supplier unlocks live in one place.\n-- Fireworks reference these ids through FireworkConfig.Supplier.\n\nexport type Supplier = {\n\tId: string,\n\tName: string,\n\tUnlockStage: number, -- BuildingConfig stage required\n\tOrder: number,\n}\n\nlocal LIST: { Supplier } = {\n\t{ Id = \"LocalWholesale\", Name = \"Local Wholesale\", UnlockStage = 1, Order = 1 },\n\t{ Id = \"RegionalDistributor\", Name = \"Regional Distributor\", UnlockStage = 3, Order = 2 },\n\t{ Id = \"PremiumImports\", Name = \"Premium Imports\", UnlockStage = 4, Order = 3 },\n\t{ Id = \"EliteFireworks\", Name = \"Elite Fireworks\", UnlockStage = 6, Order = 4 },\n\t{ Id = \"GalacticSupplier\", Name = \"Galactic Supplier\", UnlockStage = 8, Order = 5 },\n}\n\nlocal byId: { [string]: Supplier } = {}\nfor _, s in LIST do\n\tbyId[s.Id] = s\nend\n\nlocal SupplierConfig = {}\nSupplierConfig.List = LIST\n\nfunction SupplierConfig.Get(id: string): Supplier?\n\treturn byId[id]\nend\n\nfunction SupplierConfig.IsUnlocked(id: string, businessStage: number): boolean\n\tlocal s = byId[id]\n\treturn s ~= nil and businessStage >= s.UnlockStage\nend\n\nreturn SupplierConfig\n"},
{"ReplicatedStorage/Shared/Types","ModuleScript","--!strict\n-- Shared type definitions (ModuleScript). Types only; nothing to require at runtime.\n\nexport type Rarity = \"Common\" | \"Uncommon\" | \"Rare\" | \"Epic\" | \"Legendary\" | \"Mythical\" | \"Secret\"\n\nexport type FireworkDef = {\n\tId: string,\n\tDisplayName: string,\n\tDescription: string,\n\tRarity: Rarity,\n\tWholesaleCost: number,\n\tRetailPrice: number, -- recommended retail price\n\tSupplierStock: { Min: number, Max: number }, -- quantity range per restock\n\tSupplier: string, -- SupplierConfig id\n\tUnlockLevel: number, -- business stage required (BuildingConfig)\n\tDemand: number, -- base customer demand multiplier (1 = average)\n\tModel: string, -- name of the inventory model in ServerStorage.FireworkModels\n\tEffect: string, -- id looked up by the Phase 3 FireworkEffects module\n\tXPReward: number,\n}\n\nexport type PlayerStats = {\n\tLifetimeEarnings: number,\n\tLifetimeSpent: number,\n\tFireworksSold: number,\n\tFireworksLaunched: number,\n\tCustomersServed: number,\n\tSessions: number,\n}\n\nexport type PlayerData = {\n\tVersion: number,\n\tCash: number,\n\tXP: number,\n\tLevel: number,\n\tBusinessStage: number,\n\tBusinessName: string,\n\tInventory: { [string]: number },\n\tShelfInventory: { [string]: any },\n\tPlacedObjects: { any },\n\tEmployees: { [string]: any },\n\tEmployeeUpgrades: { [string]: number },\n\tCollection: {\n\t\tDiscovered: { [string]: boolean },\n\t\tPurchased: { [string]: boolean },\n\t\tLaunched: { [string]: boolean },\n\t},\n\tReputation: number,\n\tQuests: { [string]: any },\n\tAchievements: { [string]: boolean },\n\tPrestige: { Count: number, Points: number },\n\tSettings: { [string]: any },\n\tEntitlements: { [string]: boolean },\n\tProcessedReceipts: { [string]: boolean },\n\tStats: PlayerStats,\n\tTutorial: { Completed: boolean, Step: number },\n\tFirstJoin: number,\n\tLastLogout: number,\n}\n\nreturn {}\n"},
{"ReplicatedStorage/Shared/Utilities/Format","ModuleScript","--!strict\n-- Format (ModuleScript). Number/time formatting shared by client and server.\n\nlocal Format = {}\n\nfunction Format.Commas(n: number): string\n\tlocal sign = if n < 0 then \"-\" else \"\"\n\tlocal digits = tostring(math.floor(math.abs(n)))\n\tlocal out = digits:reverse():gsub(\"(%d%d%d)\", \"%1,\"):reverse()\n\tout = out:gsub(\"^,\", \"\")\n\treturn sign .. out\nend\n\nlocal SUFFIXES = {\n\t{ 1e15, \"Q\" },\n\t{ 1e12, \"T\" },\n\t{ 1e9, \"B\" },\n\t{ 1e6, \"M\" },\n}\n\n-- \"$1,250\" below one million, \"$1.25M\" above.\nfunction Format.Money(n: number): string\n\tlocal abs = math.abs(n)\n\tfor _, entry in SUFFIXES do\n\t\tif abs >= entry[1] then\n\t\t\tlocal scaled = string.format(\"%.2f\", n / entry[1])\n\t\t\tscaled = scaled:gsub(\"%.?0+$\", \"\")\n\t\t\treturn \"$\" .. scaled .. entry[2]\n\t\tend\n\tend\n\treturn (if n < 0 then \"-$\" else \"$\") .. Format.Commas(abs)\nend\n\nfunction Format.Clock(seconds: number): string\n\tseconds = math.max(0, math.floor(seconds))\n\treturn string.format(\"%d:%02d\", seconds // 60, seconds % 60)\nend\n\nreturn Format\n"},
{"ReplicatedStorage/Shared/Utilities/RemoteRegistry","ModuleScript","-- RemoteRegistry (ModuleScript). One place to create/fetch remotes. The server creates them on demand;\n-- clients wait for them. All remotes live in ReplicatedStorage.Remotes.\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal RemoteRegistry = {}\n\nlocal function getFolder(): Folder\n\tlocal folder = ReplicatedStorage:FindFirstChild(\"Remotes\")\n\tif folder then\n\t\treturn folder\n\tend\n\tif RunService:IsServer() then\n\t\tfolder = Instance.new(\"Folder\")\n\t\tfolder.Name = \"Remotes\"\n\t\tfolder.Parent = ReplicatedStorage\n\t\treturn folder\n\tend\n\treturn ReplicatedStorage:WaitForChild(\"Remotes\")\nend\n\nlocal function get(name: string, className: string): Instance\n\tlocal folder = getFolder()\n\tlocal existing = folder:FindFirstChild(name)\n\tif existing then\n\t\treturn existing\n\tend\n\tif RunService:IsServer() then\n\t\tlocal remote = Instance.new(className)\n\t\tremote.Name = name\n\t\tremote.Parent = folder\n\t\treturn remote\n\tend\n\treturn folder:WaitForChild(name, 30)\nend\n\nfunction RemoteRegistry.Event(name: string): RemoteEvent\n\treturn get(name, \"RemoteEvent\") :: RemoteEvent\nend\n\nfunction RemoteRegistry.Function(name: string): RemoteFunction\n\treturn get(name, \"RemoteFunction\") :: RemoteFunction\nend\n\nreturn RemoteRegistry\n"},
{"ReplicatedStorage/Shared/Utilities/Signal","ModuleScript","-- Signal (ModuleScript). Tiny event class so services don't need BindableEvents.\n\nlocal Signal = {}\nSignal.__index = Signal\n\nfunction Signal.new()\n\treturn setmetatable({ _handlers = {} }, Signal)\nend\n\nfunction Signal:Connect(fn)\n\tlocal handler = { fn = fn }\n\ttable.insert(self._handlers, handler)\n\tlocal handlers = self._handlers\n\tlocal connection = {}\n\tfunction connection.Disconnect()\n\t\tlocal index = table.find(handlers, handler)\n\t\tif index then\n\t\t\ttable.remove(handlers, index)\n\t\tend\n\tend\n\treturn connection\nend\n\nfunction Signal:Fire(...)\n\tfor _, handler in table.clone(self._handlers) do\n\t\ttask.spawn(handler.fn, ...)\n\tend\nend\n\nreturn Signal\n"},
{"ServerScriptService/Builders/BuildUtil","ModuleScript","-- BuildUtil (ModuleScript, server only). Helpers for procedurally generated placeholder geometry.\n-- Everything built with these is a stand-in: swap for real models later without touching game logic,\n-- because gameplay code only looks at the named parts / attributes (Role, ShelfId...).\n\nlocal BuildUtil = {}\n\nfunction BuildUtil.Part(\n\tparent: Instance,\n\tname: string,\n\tsize: Vector3,\n\tcframe: CFrame,\n\tcolor: Color3,\n\tmaterial: Enum.Material?\n): Part\n\tlocal part = Instance.new(\"Part\")\n\tpart.Name = name\n\tpart.Anchored = true\n\tpart.Size = size\n\tpart.CFrame = cframe\n\tpart.Color = color\n\tpart.Material = material or Enum.Material.SmoothPlastic\n\tpart.TopSurface = Enum.SurfaceType.Smooth\n\tpart.BottomSurface = Enum.SurfaceType.Smooth\n\tpart.Parent = parent\n\treturn part\nend\n\n-- Adds readable text on one face of a part. Returns the TextLabel so callers can change the text later.\nfunction BuildUtil.Label(part: BasePart, text: string, face: Enum.NormalId, textColor: Color3?, background: Color3?): TextLabel\n\tlocal gui = Instance.new(\"SurfaceGui\")\n\tgui.Name = \"Label_\" .. face.Name\n\tgui.Face = face\n\tgui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n\tgui.PixelsPerStud = 40\n\tgui.LightInfluence = 0.2\n\tgui.Parent = part\n\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Name = \"Text\"\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = if background then 0 else 1\n\tif background then\n\t\tlabel.BackgroundColor3 = background\n\tend\n\tlabel.TextColor3 = textColor or Color3.fromRGB(40, 30, 30)\n\tlabel.Font = Enum.Font.FredokaOne\n\tlabel.TextScaled = true\n\tlabel.Text = text\n\tlabel.Parent = gui\n\n\tlocal padding = Instance.new(\"UIPadding\")\n\tpadding.PaddingTop = UDim.new(0, 8)\n\tpadding.PaddingBottom = UDim.new(0, 8)\n\tpadding.PaddingLeft = UDim.new(0, 8)\n\tpadding.PaddingRight = UDim.new(0, 8)\n\tpadding.Parent = label\n\n\treturn label\nend\n\nreturn BuildUtil\n"},
{"ServerScriptService/Builders/MapBuilder","ModuleScript","-- MapBuilder (ModuleScript, server only)\n-- Builds a placeholder low-poly town at runtime if Workspace.PlayerPlots does not exist yet:\n-- ground, central wholesale supplier, six plots on a ring, roads, leaderboard plaza, public arena, event area, trees.\n--\n-- To use your own hand-built map instead: create Workspace.PlayerPlots containing models named Plot_1..Plot_6.\n-- Each model needs a Part called \"Base\" (front of the plot = the Base's -Z side) and optionally a Part\n-- called \"OwnerSign\" with a SurfaceGui > TextLabel. MapBuilder will then skip generation.\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Lighting = game:GetService(\"Lighting\")\n\nlocal BuildUtil = require(script.Parent.BuildUtil)\n\nlocal MapBuilder = {}\n\nlocal PLOT_COUNT = 6\nlocal RING_RADIUS = 150\nlocal PLOT_SIZE = 70\nlocal SURFACE_Y = 0.4 -- top of plots and plazas\n\nexport type PlotRecord = { Model: Model, Base: BasePart }\n\nlocal GRASS = Color3.fromRGB(110, 190, 80)\nlocal PLOT_GRASS = Color3.fromRGB(135, 205, 95)\nlocal ROAD = Color3.fromRGB(70, 72, 80)\nlocal CONCRETE = Color3.fromRGB(190, 190, 195)\n\nlocal function newFolder(name: string, parent: Instance): Folder\n\tlocal folder = Instance.new(\"Folder\")\n\tfolder.Name = name\n\tfolder.Parent = parent\n\treturn folder\nend\n\nlocal function collect(folder: Instance): { PlotRecord }\n\tlocal list = {}\n\tfor _, model in folder:GetChildren() do\n\t\tlocal base = model:FindFirstChild(\"Base\")\n\t\tif model:IsA(\"Model\") and base and base:IsA(\"BasePart\") then\n\t\t\ttable.insert(list, { Model = model, Base = base })\n\t\tend\n\tend\n\ttable.sort(list, function(a, b)\n\t\treturn a.Model.Name < b.Model.Name\n\tend)\n\treturn list\nend\n\nlocal function buildTree(parent: Instance, position: Vector3, rng: Random)\n\tlocal height = rng:NextNumber(5, 8)\n\tBuildUtil.Part(parent, \"Trunk\", Vector3.new(1.5, height, 1.5), CFrame.new(position + Vector3.new(0, height / 2, 0)), Color3.fromRGB(120, 85, 55), Enum.Material.Wood)\n\tlocal leaves = BuildUtil.Part(parent, \"Leaves\", Vector3.new(9, 9, 9), CFrame.new(position + Vector3.new(0, height + 3, 0)), Color3.fromRGB(70, 160, 70), Enum.Material.Grass)\n\tleaves.Shape = Enum.PartType.Ball\n\tleaves.CanCollide = false\nend\n\nlocal function buildSignBoard(parent: Instance, name: string, text: string, position: Vector3, facing: Vector3, size: Vector3?, color: Color3?)\n\tlocal boardSize = size or Vector3.new(24, 8, 1)\n\tlocal board = BuildUtil.Part(parent, name, boardSize, CFrame.lookAt(position, position + facing), color or Color3.fromRGB(255, 244, 214))\n\t-- the board's Front face looks along its -Z; lookAt points -Z at `facing`, so label the Front\n\tBuildUtil.Label(board, text, Enum.NormalId.Front, Color3.fromRGB(150, 40, 40))\n\treturn board\nend\n\nlocal function generate(): Folder\n\tlocal map = Workspace:FindFirstChild(\"Map\")\n\tif map then\n\t\tmap:Destroy()\n\tend\n\tlocal mapFolder = newFolder(\"Map\", Workspace)\n\tlocal plotsFolder = newFolder(\"PlayerPlots\", Workspace)\n\tlocal roads = newFolder(\"Roads\", mapFolder)\n\tlocal decor = newFolder(\"Decor\", mapFolder)\n\tnewFolder(\"NPCSpawnPoints\", Workspace)\n\n\tlocal hub = Vector3.new(0, SURFACE_Y / 2, 0)\n\n\t-- Ground\n\tBuildUtil.Part(mapFolder, \"Ground\", Vector3.new(760, 2, 760), CFrame.new(0, -1, 0), GRASS, Enum.Material.Grass)\n\n\t-- Central plaza + wholesale supplier\n\tlocal plaza = BuildUtil.Part(mapFolder, \"HubPlaza\", Vector3.new(SURFACE_Y, 110, 110), CFrame.new(hub) * CFrame.Angles(0, 0, math.rad(90)), CONCRETE, Enum.Material.Concrete)\n\tplaza.Shape = Enum.PartType.Cylinder\n\n\tlocal supplier = Instance.new(\"Model\")\n\tsupplier.Name = \"WholesaleSupplier\"\n\tsupplier.Parent = mapFolder\n\tlocal body = BuildUtil.Part(supplier, \"Body\", Vector3.new(28, 12, 22), CFrame.new(0, SURFACE_Y + 6, 0), Color3.fromRGB(215, 70, 60))\n\tBuildUtil.Part(supplier, \"Roof\", Vector3.new(30, 1.5, 24), CFrame.new(0, SURFACE_Y + 12.75, 0), Color3.fromRGB(90, 55, 45))\n\tfor _, face in { Enum.NormalId.Front, Enum.NormalId.Back, Enum.NormalId.Left, Enum.NormalId.Right } do\n\t\tBuildUtil.Label(body, \"WHOLESALE\", face, Color3.new(1, 1, 1))\n\tend\n\n\t-- Spawn pad inside the hub (players are moved to their plot once their data loads)\n\tlocal spawn = Instance.new(\"SpawnLocation\")\n\tspawn.Name = \"HubSpawn\"\n\tspawn.Anchored = true\n\tspawn.Size = Vector3.new(10, 1, 10)\n\tspawn.Position = Vector3.new(-30, 0.9, -30)\n\tspawn.Neutral = true\n\tspawn.Duration = 0\n\tspawn.Color = Color3.fromRGB(255, 196, 61)\n\tspawn.Material = Enum.Material.SmoothPlastic\n\tspawn.Parent = mapFolder\n\n\t-- Leaderboard plaza (Phase 6 attaches the boards)\n\tBuildUtil.Part(mapFolder, \"LeaderboardPlaza\", Vector3.new(16, 0.3, 34), CFrame.new(40, SURFACE_Y + 0.15, 0), Color3.fromRGB(255, 220, 120))\n\tbuildSignBoard(mapFolder, \"LeaderboardBoard\", \"LEADERBOARDS\", Vector3.new(47, SURFACE_Y + 6, 0), Vector3.new(-1, 0, 0), Vector3.new(30, 9, 1), Color3.fromRGB(255, 244, 214))\n\n\t-- Public arena and event area\n\tBuildUtil.Part(mapFolder, \"PublicFireworkArena\", Vector3.new(130, 0.4, 130), CFrame.new(300, 0.2, 0), Color3.fromRGB(80, 84, 100), Enum.Material.Slate)\n\tbuildSignBoard(mapFolder, \"ArenaSign\", \"PUBLIC FIREWORK ARENA\", Vector3.new(240, 15, 0), Vector3.new(-1, 0, 0), Vector3.new(40, 8, 1))\n\tBuildUtil.Part(mapFolder, \"EventArea\", Vector3.new(100, 0.4, 100), CFrame.new(-300, 0.2, 0), Color3.fromRGB(110, 150, 230), Enum.Material.SmoothPlastic)\n\tbuildSignBoard(mapFolder, \"EventSign\", \"EVENT AREA\", Vector3.new(-250, 15, 0), Vector3.new(1, 0, 0), Vector3.new(30, 8, 1))\n\n\t-- Roads from the hub to the arena and event area\n\tBuildUtil.Part(roads, \"RoadEast\", Vector3.new(185, 0.2, 14), CFrame.new(147.5, 0.1, 0), ROAD, Enum.Material.Asphalt)\n\tBuildUtil.Part(roads, \"RoadWest\", Vector3.new(185, 0.2, 14), CFrame.new(-147.5, 0.1, 0), ROAD, Enum.Material.Asphalt)\n\n\t-- Plots on a ring. Plot k sits at 30 + 60k degrees so roads never run along the X axis.\n\tfor i = 1, PLOT_COUNT do\n\t\tlocal angle = math.rad(30 + (i - 1) * 60)\n\t\tlocal position = Vector3.new(math.cos(angle) * RING_RADIUS, SURFACE_Y / 2, math.sin(angle) * RING_RADIUS)\n\t\tlocal look = CFrame.lookAt(position, hub) -- plot -Z (its \"front\") faces the hub\n\n\t\tlocal model = Instance.new(\"Model\")\n\t\tmodel.Name = \"Plot_\" .. i\n\t\tmodel:SetAttribute(\"PlotIndex\", i)\n\t\tmodel.Parent = plotsFolder\n\n\t\tlocal base = BuildUtil.Part(model, \"Base\", Vector3.new(PLOT_SIZE, SURFACE_Y, PLOT_SIZE), look, PLOT_GRASS, Enum.Material.Grass)\n\t\tmodel.PrimaryPart = base\n\n\t\t-- Owner sign on the front-left corner, readable from the road\n\t\tlocal signPost = BuildUtil.Part(model, \"OwnerSignPost\", Vector3.new(0.8, 6, 0.8), look * CFrame.new(-27, 3 + SURFACE_Y / 2, -32), Color3.fromRGB(120, 85, 55), Enum.Material.Wood)\n\t\tsignPost.CanCollide = true\n\t\tlocal sign = BuildUtil.Part(model, \"OwnerSign\", Vector3.new(14, 4, 0.6), look * CFrame.new(-27, 7.5, -32), Color3.fromRGB(255, 244, 214))\n\t\tBuildUtil.Label(sign, \"FOR SALE\", Enum.NormalId.Front, Color3.fromRGB(150, 40, 40))\n\n\t\t-- Road from the hub to the front of the plot\n\t\tlocal roadLength = RING_RADIUS - PLOT_SIZE / 2 - 50\n\t\tlocal mid = hub:Lerp(position, (50 + roadLength / 2) / RING_RADIUS)\n\t\tBuildUtil.Part(roads, \"PlotRoad_\" .. i, Vector3.new(14, 0.2, roadLength), CFrame.lookAt(Vector3.new(mid.X, 0.1, mid.Z), Vector3.new(0, 0.1, 0)), ROAD, Enum.Material.Asphalt)\n\tend\n\n\t-- Trees (deterministic so every server looks the same)\n\tlocal rng = Random.new(7)\n\tlocal placed = 0\n\twhile placed < 45 do\n\t\tlocal angle = rng:NextNumber(0, math.pi * 2)\n\t\tlocal radius = rng:NextNumber(205, 260)\n\t\tif math.abs(math.sin(angle)) > 0.3 then\n\t\t\tbuildTree(decor, Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius), rng)\n\t\t\tplaced += 1\n\t\tend\n\tend\n\n\treturn plotsFolder\nend\n\nfunction MapBuilder.Build(): { PlotRecord }\n\tfor _, name in { \"Baseplate\", \"SpawnLocation\" } do\n\t\tif Workspace:FindFirstChild(name) then\n\t\t\twarn((\"[MapBuilder] Workspace.%s exists and will overlap the generated map. Delete it.\"):format(name))\n\t\tend\n\tend\n\n\tLighting.ClockTime = 14.5 -- day/night cycle arrives in Phase 7\n\n\tlocal existing = Workspace:FindFirstChild(\"PlayerPlots\")\n\tlocal folder = if existing then existing else generate()\n\tlocal plots = collect(folder)\n\tif #plots == 0 then\n\t\twarn(\"[MapBuilder] Workspace.PlayerPlots has no valid Plot models (need a Model with a Part named 'Base').\")\n\tend\n\treturn plots\nend\n\nreturn MapBuilder\n"},
{"ServerScriptService/Builders/StandBuilder","ModuleScript","-- StandBuilder (ModuleScript, server only)\n-- Builds the placeholder business for a given stage inside a plot, and returns \"anchors\": the named parts and\n-- CFrames later phases attach gameplay to (checkout, shelves, delivery area, launch area, supplier computer...).\n--\n-- Only stage 1 (Roadside Tent) exists in Phase 1. Higher stages fall back to it until Phase 4.\n-- Plot-local axes: -Z is the front (road side), +Z is the back, +X is to the right when facing the back.\n\nlocal BuildUtil = require(script.Parent.BuildUtil)\n\nlocal StandBuilder = {}\n\nexport type Anchors = {\n\tOrigin: CFrame, -- centre of the plot surface\n\tCheckout: BasePart,\n\tShelves: { Model },\n\tSupplierComputer: BasePart,\n\tDeliveryArea: BasePart,\n\tLaunchArea: BasePart,\n\tPlayerSpawn: CFrame,\n\tCustomerSpawn: CFrame, -- where customers appear (front edge of the plot)\n\tQueueStart: CFrame, -- front of the checkout counter\n\tSign: TextLabel,\n}\n\nlocal WOOD = Color3.fromRGB(160, 110, 70)\nlocal DARK_WOOD = Color3.fromRGB(110, 75, 50)\nlocal CLOTH = Color3.fromRGB(225, 70, 65)\n\nlocal function buildTent(stand: Model, at: (number, number, number) -> CFrame, businessName: string): Anchors\n\tlocal origin = at(0, 0, 0)\n\n\t-- Floor boards under the tent\n\tBuildUtil.Part(stand, \"TentFloor\", Vector3.new(18, 0.3, 14), at(0, 0.15, 4), Color3.fromRGB(200, 165, 120), Enum.Material.WoodPlanks)\n\n\t-- Four poles\n\tfor _, x in { -8, 8 } do\n\t\tfor _, z in { -3, 11 } do\n\t\t\tBuildUtil.Part(stand, \"Pole\", Vector3.new(0.6, 7.6, 0.6), at(x, 3.8, z), DARK_WOOD, Enum.Material.Wood)\n\t\tend\n\tend\n\n\t-- Gable roof: ridge along X at z = 4. Front panel slopes toward -Z, back panel toward +Z.\n\tlocal slope = math.rad(20)\n\tlocal front = BuildUtil.Part(stand, \"RoofFront\", Vector3.new(19, 0.4, 7.5), at(0, 8.7, 0.5) * CFrame.Angles(-slope, 0, 0), CLOTH, Enum.Material.Fabric)\n\tlocal back = BuildUtil.Part(stand, \"RoofBack\", Vector3.new(19, 0.4, 7.5), at(0, 8.7, 7.5) * CFrame.Angles(slope, 0, 0), Color3.fromRGB(245, 240, 230), Enum.Material.Fabric)\n\tfront.CanCollide = false\n\tback.CanCollide = false\n\n\t-- Checkout counter at the front edge of the tent\n\tlocal checkout = BuildUtil.Part(stand, \"Checkout\", Vector3.new(8, 3, 2.5), at(0, 1.5, -1), WOOD, Enum.Material.Wood)\n\tcheckout:SetAttribute(\"Role\", \"Checkout\")\n\tlocal register = BuildUtil.Part(stand, \"Register\", Vector3.new(2.2, 1.2, 1.6), at(2, 3.6, -1), Color3.fromRGB(40, 42, 50))\n\tregister.CanCollide = false\n\tBuildUtil.Label(register, \"$\", Enum.NormalId.Back, Color3.fromRGB(120, 255, 150))\n\n\t-- One basic wooden shelf on the back wall\n\tlocal shelf = Instance.new(\"Model\")\n\tshelf.Name = \"Shelf_1\"\n\tshelf:SetAttribute(\"ShelfId\", 1)\n\tshelf:SetAttribute(\"ShelfType\", \"BasicWooden\")\n\tshelf.Parent = stand\n\tlocal backPanel = BuildUtil.Part(shelf, \"BackPanel\", Vector3.new(8, 4.6, 0.4), at(0, 2.6, 10.6), DARK_WOOD, Enum.Material.Wood)\n\tfor index, y in { 0.9, 2.2, 3.5 } do\n\t\tlocal board = BuildUtil.Part(shelf, \"Board_\" .. index, Vector3.new(8, 0.3, 1.8), at(0, y, 9.8), WOOD, Enum.Material.Wood)\n\t\tboard:SetAttribute(\"Role\", \"ShelfBoard\")\n\tend\n\tshelf.PrimaryPart = backPanel\n\n\t-- Order computer (Phase 2 attaches the supplier UI here)\n\tlocal desk = BuildUtil.Part(stand, \"SupplierComputer\", Vector3.new(3, 3, 2), at(-6.5, 1.5, 7), Color3.fromRGB(70, 74, 90))\n\tdesk:SetAttribute(\"Role\", \"SupplierComputer\")\n\tBuildUtil.Label(desk, \"ORDER\", Enum.NormalId.Front, Color3.fromRGB(120, 220, 255), Color3.fromRGB(25, 30, 45))\n\n\t-- Delivery area (left of the tent, near the road)\n\tlocal delivery = BuildUtil.Part(stand, \"DeliveryArea\", Vector3.new(14, 0.2, 10), at(-22, 0.1, -12), Color3.fromRGB(255, 205, 60))\n\tdelivery:SetAttribute(\"Role\", \"DeliveryArea\")\n\tBuildUtil.Label(delivery, \"DELIVERIES\", Enum.NormalId.Top, Color3.fromRGB(110, 70, 20))\n\n\t-- Small outdoor launch area behind the tent\n\tlocal launch = BuildUtil.Part(stand, \"LaunchArea\", Vector3.new(26, 0.2, 18), at(0, 0.1, 24), Color3.fromRGB(70, 74, 90), Enum.Material.Slate)\n\tlaunch:SetAttribute(\"Role\", \"LaunchArea\")\n\tBuildUtil.Label(launch, \"LAUNCH AREA\", Enum.NormalId.Top, Color3.fromRGB(255, 230, 120))\n\n\t-- Roadside sign with the business name\n\tBuildUtil.Part(stand, \"SignPost\", Vector3.new(0.8, 6, 0.8), at(14, 3, -14), DARK_WOOD, Enum.Material.Wood)\n\tlocal sign = BuildUtil.Part(stand, \"BusinessSign\", Vector3.new(11, 3.6, 0.6), at(14, 7.4, -14), Color3.fromRGB(255, 244, 214))\n\tlocal signLabel = BuildUtil.Label(sign, businessName, Enum.NormalId.Front, Color3.fromRGB(150, 40, 40))\n\n\treturn {\n\t\tOrigin = origin,\n\t\tCheckout = checkout,\n\t\tShelves = { shelf },\n\t\tSupplierComputer = desk,\n\t\tDeliveryArea = delivery,\n\t\tLaunchArea = launch,\n\t\tPlayerSpawn = at(0, 0, -14) * CFrame.Angles(0, math.pi, 0), -- facing the tent\n\t\tCustomerSpawn = at(26, 0, -33),\n\t\tQueueStart = at(0, 0, -6) * CFrame.Angles(0, math.pi, 0),\n\t\tSign = signLabel,\n\t}\nend\n\nfunction StandBuilder.Build(plotModel: Model, base: BasePart, stage: number, businessName: string): Anchors\n\tlocal existing = plotModel:FindFirstChild(\"Stand\")\n\tif existing then\n\t\texisting:Destroy()\n\tend\n\tif stage > 1 then\n\t\twarn(\"[StandBuilder] Stage \" .. stage .. \" models arrive in Phase 4; building the Roadside Tent instead.\")\n\tend\n\n\tlocal stand = Instance.new(\"Model\")\n\tstand.Name = \"Stand\"\n\n\tlocal origin = base.CFrame * CFrame.new(0, base.Size.Y / 2, 0)\n\tlocal function at(x: number, y: number, z: number): CFrame\n\t\treturn origin * CFrame.new(x, y, z)\n\tend\n\n\tlocal anchors = buildTent(stand, at, businessName)\n\tstand.Parent = plotModel\n\treturn anchors\nend\n\nreturn StandBuilder\n"},
{"ServerScriptService/Security","ModuleScript","-- Security (ModuleScript, server only). Rate limiting + suspicious-activity logging for every remote.\n-- Usage in a remote handler:\n--   if not Security.RateLimit(player, \"BuyItem\", 10, 5) then return end\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Security = {}\n\nlocal buckets: { [Player]: { [string]: { count: number, windowStart: number } } } = {}\nlocal flagCounts: { [Player]: number } = {}\n\n-- Allows `maxCalls` calls per `windowSeconds` for the (player, key) pair.\nfunction Security.RateLimit(player: Player, key: string, maxCalls: number, windowSeconds: number): boolean\n\tlocal playerBuckets = buckets[player]\n\tif not playerBuckets then\n\t\tplayerBuckets = {}\n\t\tbuckets[player] = playerBuckets\n\tend\n\tlocal now = os.clock()\n\tlocal bucket = playerBuckets[key]\n\tif not bucket or now - bucket.windowStart >= windowSeconds then\n\t\tplayerBuckets[key] = { count = 1, windowStart = now }\n\t\treturn true\n\tend\n\tbucket.count += 1\n\tif bucket.count > maxCalls then\n\t\tif bucket.count == maxCalls + 1 then\n\t\t\tSecurity.Flag(player, \"RateLimit\", key)\n\t\tend\n\t\treturn false\n\tend\n\treturn true\nend\n\n-- Logs suspicious activity. Phase 7 will forward this to analytics/webhooks.\nfunction Security.Flag(player: Player, reason: string, detail: string?)\n\tflagCounts[player] = (flagCounts[player] or 0) + 1\n\twarn((\"[Security] %s (%d) flagged: %s %s\"):format(player.Name, player.UserId, reason, detail or \"\"))\nend\n\nfunction Security.FlagCount(player: Player): number\n\treturn flagCounts[player] or 0\nend\n\n-- Numeric validation helpers for remote arguments.\nfunction Security.IsFiniteNumber(value: any): boolean\n\treturn type(value) == \"number\" and value == value and value > -math.huge and value < math.huge\nend\n\nfunction Security.IsIntegerInRange(value: any, min: number, max: number): boolean\n\treturn Security.IsFiniteNumber(value) and value == math.floor(value) and value >= min and value <= max\nend\n\nPlayers.PlayerRemoving:Connect(function(player)\n\tbuckets[player] = nil\n\tflagCounts[player] = nil\nend)\n\nreturn Security\n"},
{"ServerScriptService/ServerMain","Script","-- ServerMain (Script, server only). Boots every service in dependency order.\n-- DataService is initialised LAST so every other service has already subscribed to ProfileLoaded.\n\nlocal RunService = game:GetService(\"RunService\")\nlocal ServerStorage = game:GetService(\"ServerStorage\")\n\nlocal Services = script.Parent:WaitForChild(\"Services\")\n\nlocal ORDER = {\n\t\"StateService\",\n\t\"EconomyService\",\n\t\"PlotService\",\n\t\"DataService\",\n}\n\nlocal loaded: { [string]: any } = {}\nlocal failures = 0\n\nfor _, name in ORDER do\n\tlocal module = Services:WaitForChild(name)\n\tlocal ok, service = pcall(require, module)\n\tif not ok then\n\t\tfailures += 1\n\t\twarn((\"[ServerMain] Failed to load %s: %s\"):format(name, tostring(service)))\n\telse\n\t\tloaded[name] = service\n\t\tif type(service) == \"table\" and service.Init then\n\t\t\tlocal initOk, err = pcall(service.Init)\n\t\t\tif not initOk then\n\t\t\t\tfailures += 1\n\t\t\t\twarn((\"[ServerMain] %s.Init failed: %s\"):format(name, tostring(err)))\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- Studio-only test hook. The command bar keeps its own module cache, so require()-ing a service there gives a\n-- fresh copy with no player data. Invoke this instead (Server context):\n--   game.ServerStorage.DebugEconomy:Invoke(\"AddCash\", game.Players:GetPlayers()[1], 250)\n-- Never created on live servers.\nif RunService:IsStudio() and loaded.EconomyService then\n\tlocal economy = loaded.EconomyService\n\tlocal hook = Instance.new(\"BindableFunction\")\n\thook.Name = \"DebugEconomy\"\n\thook.OnInvoke = function(method: string, player: Player, amount: number)\n\t\tlocal fn = economy[method]\n\t\tif type(fn) ~= \"function\" then\n\t\t\treturn (\"unknown method %s (use AddCash, TrySpend, AddXP, GetCash)\"):format(tostring(method))\n\t\tend\n\t\treturn fn(player, amount, \"Debug\")\n\tend\n\thook.Parent = ServerStorage\nend\n\nif failures == 0 then\n\tprint(\"[ServerMain] Run a Firework Stand - Phase 1 server ready\")\nelse\n\twarn((\"[ServerMain] Phase 1 server started with %d error(s); see warnings above\"):format(failures))\nend\n"},
{"ServerScriptService/Services/DataService","ModuleScript","-- DataService (ModuleScript, server only)\n--\n-- Persistent player data with:\n--   * session locking (a record can only be owned by one server at a time; locks expire if a server crashes)\n--   * UpdateAsync everywhere (no blind SetAsync overwrites)\n--   * retry with backoff on load and save\n--   * data versioning + migrations + default reconciliation\n--   * autosave, save-on-leave, save-on-shutdown (BindToClose)\n--   * NEVER substituting defaults when a load fails: the player is kicked instead.\n--     (Studio-only exception: an \"ephemeral\" profile that is never written, so you can test without API access.)\n--\n-- Stored record shape in the DataStore:  { Lock = { JobId, Time }, Data = <PlayerData> }\n\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Signal = require(Shared.Utilities.Signal)\nlocal EconomyConfig = require(Shared.Config.EconomyConfig)\n\nlocal STORE_NAME = \"RunAFireworkStand_PlayerData_v1\"\nlocal KEY_PREFIX = \"Player_\"\nlocal SCHEMA_VERSION = 1\n\nlocal AUTOSAVE_INTERVAL = 60\nlocal LOCK_TIMEOUT = 180 -- seconds; must stay > 2x AUTOSAVE_INTERVAL\nlocal LOAD_ATTEMPTS = if RunService:IsStudio() then 1 else 5\nlocal SAVE_ATTEMPTS = 5\n\nlocal DataService = {}\nDataService.ProfileLoaded = Signal.new() -- (player, data)\n\n-- GetDataStore itself throws in an unpublished place, so guard it. If it fails, every load reports \"error\":\n-- Studio then falls back to a temporary profile and live servers kick (live servers are always published).\nlocal storeOk, storeOrError = pcall(function()\n\treturn DataStoreService:GetDataStore(STORE_NAME)\nend)\nlocal store: DataStore? = if storeOk then storeOrError else nil\nlocal storeError = if storeOk then \"\" else tostring(storeOrError)\nif not storeOk then\n\twarn(\"[DataService] DataStore unavailable: \" .. storeError)\nend\n\ntype Profile = {\n\tPlayer: Player,\n\tUserId: number,\n\tData: any,\n\tEphemeral: boolean,\n\tSaving: boolean,\n\tReleasing: boolean,\n}\n\nlocal Profiles: { [Player]: Profile } = {}\nlocal Waiters: { [Player]: { thread } } = {}\nlocal ReleasingHandlers: { (Player, any) -> () } = {}\n\n---------------------------------------------------------------------\n-- Template, migration, reconcile\n---------------------------------------------------------------------\n\nlocal function buildTemplate()\n\treturn {\n\t\tVersion = SCHEMA_VERSION,\n\t\tCash = EconomyConfig.StartingCash,\n\t\tXP = 0,\n\t\tLevel = 1,\n\t\tBusinessStage = 1,\n\t\tBusinessName = \"\",\n\t\tInventory = {}, -- [fireworkId] = count\n\t\tShelfInventory = {},\n\t\tPlacedObjects = {},\n\t\tEmployees = {},\n\t\tEmployeeUpgrades = {},\n\t\tCollection = { Discovered = {}, Purchased = {}, Launched = {} },\n\t\tReputation = 0,\n\t\tQuests = {},\n\t\tAchievements = {},\n\t\tPrestige = { Count = 0, Points = 0 },\n\t\tSettings = {\n\t\t\tReducedFlash = false,\n\t\t\tReducedParticles = false,\n\t\t\tMusicVolume = 0.5,\n\t\t\tSfxVolume = 0.8,\n\t\t\tFireworkVolume = 1,\n\t\t},\n\t\tEntitlements = {},\n\t\tProcessedReceipts = {}, -- developer product PurchaseIds (idempotency, Phase 7)\n\t\tStats = {\n\t\t\tLifetimeEarnings = 0,\n\t\t\tLifetimeSpent = 0,\n\t\t\tFireworksSold = 0,\n\t\t\tFireworksLaunched = 0,\n\t\t\tCustomersServed = 0,\n\t\t\tSessions = 0,\n\t\t},\n\t\tTutorial = { Completed = false, Step = 0 },\n\t\tFirstJoin = 0,\n\t\tLastLogout = 0,\n\t}\nend\n\n-- Migrations[n] upgrades data from version n to n + 1. Add a function here whenever SCHEMA_VERSION increases.\nlocal Migrations: { [number]: (any) -> () } = {}\n\nlocal function deepCopy(value: any): any\n\tif type(value) ~= \"table\" then\n\t\treturn value\n\tend\n\tlocal copy = {}\n\tfor k, v in value do\n\t\tcopy[k] = deepCopy(v)\n\tend\n\treturn copy\nend\n\n-- Adds any keys missing from `data` (recursively). Never removes or overwrites existing values.\nlocal function reconcile(data: any, template: any)\n\tfor key, templateValue in template do\n\t\tif data[key] == nil then\n\t\t\tdata[key] = deepCopy(templateValue)\n\t\telseif type(data[key]) == \"table\" and type(templateValue) == \"table\" then\n\t\t\treconcile(data[key], templateValue)\n\t\tend\n\tend\nend\n\nlocal function prepareData(storedData: any): (any, boolean)\n\tif storedData == nil then\n\t\tlocal fresh = buildTemplate()\n\t\tfresh.FirstJoin = os.time()\n\t\treturn fresh, true\n\tend\n\tif type(storedData) ~= \"table\" or type(storedData.Version) ~= \"number\" then\n\t\terror(\"stored data is malformed\")\n\tend\n\tif storedData.Version > SCHEMA_VERSION then\n\t\terror(\"stored data is from a newer version of the game\")\n\tend\n\twhile storedData.Version < SCHEMA_VERSION do\n\t\tlocal migrate = Migrations[storedData.Version]\n\t\tif not migrate then\n\t\t\terror(\"missing migration from version \" .. storedData.Version)\n\t\tend\n\t\tmigrate(storedData)\n\t\tstoredData.Version += 1\n\tend\n\treconcile(storedData, buildTemplate())\n\treturn storedData, false\nend\n\n---------------------------------------------------------------------\n-- DataStore access\n---------------------------------------------------------------------\n\n-- Returns \"ok\", record | \"locked\" | \"error\", message\nlocal function claimRecord(userId: number): (string, any)\n\tif not store then\n\t\treturn \"error\", storeError\n\tend\n\tlocal key = KEY_PREFIX .. userId\n\tlocal lastFailure = \"error\"\n\tlocal lastMessage = \"\"\n\tfor attempt = 1, LOAD_ATTEMPTS do\n\t\tlocal claimed = false\n\t\tlocal claimedRecord: any = nil\n\t\tlocal ok, err = pcall(function()\n\t\t\tstore:UpdateAsync(key, function(old)\n\t\t\t\tclaimed, claimedRecord = false, nil\n\t\t\t\tif type(old) == \"table\" and type(old.Lock) == \"table\" then\n\t\t\t\t\tlocal lockedByOther = old.Lock.JobId ~= game.JobId\n\t\t\t\t\tlocal fresh = os.time() - (old.Lock.Time or 0) < LOCK_TIMEOUT\n\t\t\t\t\tif lockedByOther and fresh then\n\t\t\t\t\t\treturn nil -- cancel: another server owns this record\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tlocal record = if type(old) == \"table\" then old else {}\n\t\t\t\trecord.Lock = { JobId = game.JobId, Time = os.time() }\n\t\t\t\tclaimed, claimedRecord = true, record\n\t\t\t\treturn record\n\t\t\tend)\n\t\tend)\n\t\tif ok then\n\t\t\tif claimed then\n\t\t\t\treturn \"ok\", claimedRecord\n\t\t\tend\n\t\t\tlastFailure, lastMessage = \"locked\", \"record locked by another server\"\n\t\telse\n\t\t\tlastFailure, lastMessage = \"error\", tostring(err)\n\t\tend\n\t\tif attempt < LOAD_ATTEMPTS then\n\t\t\ttask.wait(attempt * 3)\n\t\tend\n\tend\n\treturn lastFailure, lastMessage\nend\n\n-- Writes `data` if we still own the lock. Returns success, lostLock.\nlocal function writeRecord(userId: number, data: any, releasing: boolean): (boolean, boolean)\n\tlocal key = KEY_PREFIX .. userId\n\tlocal snapshot = deepCopy(data) -- copy now; the live table keeps changing while we yield\n\tlocal lostLock = false\n\tfor attempt = 1, SAVE_ATTEMPTS do\n\t\tlocal ok, err = pcall(function()\n\t\t\tstore:UpdateAsync(key, function(old)\n\t\t\t\tlostLock = false\n\t\t\t\tif type(old) == \"table\" and type(old.Lock) == \"table\" and old.Lock.JobId ~= game.JobId then\n\t\t\t\t\tlostLock = true\n\t\t\t\t\treturn nil -- another server took over; do not overwrite its data\n\t\t\t\tend\n\t\t\t\tlocal record = if type(old) == \"table\" then old else {}\n\t\t\t\trecord.Data = snapshot\n\t\t\t\tif releasing then\n\t\t\t\t\trecord.Lock = nil\n\t\t\t\telse\n\t\t\t\t\trecord.Lock = { JobId = game.JobId, Time = os.time() }\n\t\t\t\tend\n\t\t\t\treturn record\n\t\t\tend)\n\t\tend)\n\t\tif ok then\n\t\t\treturn not lostLock, lostLock\n\t\tend\n\t\twarn((\"[DataService] Save attempt %d failed for %d: %s\"):format(attempt, userId, tostring(err)))\n\t\ttask.wait(attempt * 2)\n\tend\n\treturn false, false\nend\n\n-- Releases our lock without touching stored data (used when the player left mid-load or data was unusable).\nlocal function releaseLockOnly(userId: number)\n\tpcall(function()\n\t\tstore:UpdateAsync(KEY_PREFIX .. userId, function(old)\n\t\t\tif type(old) == \"table\" and type(old.Lock) == \"table\" and old.Lock.JobId == game.JobId then\n\t\t\t\told.Lock = nil\n\t\t\t\treturn old\n\t\t\tend\n\t\t\treturn nil\n\t\tend)\n\tend)\nend\n\n---------------------------------------------------------------------\n-- Waiters\n---------------------------------------------------------------------\n\nlocal function wake(player: Player, data: any)\n\tlocal list = Waiters[player]\n\tif not list then\n\t\treturn\n\tend\n\tWaiters[player] = nil\n\tfor _, thread in list do\n\t\ttask.spawn(thread, data)\n\tend\nend\n\n---------------------------------------------------------------------\n-- Profile lifecycle\n---------------------------------------------------------------------\n\nlocal function onPlayerAdded(player: Player)\n\tlocal userId = player.UserId\n\tlocal status, record = claimRecord(userId)\n\n\tif not player:IsDescendantOf(Players) then\n\t\tif status == \"ok\" then\n\t\t\treleaseLockOnly(userId)\n\t\tend\n\t\twake(player, nil)\n\t\treturn\n\tend\n\n\tlocal data: any = nil\n\tlocal ephemeral = false\n\n\tif status == \"ok\" then\n\t\tlocal prepared, result = pcall(prepareData, record.Data)\n\t\tif prepared then\n\t\t\tdata = result\n\t\telse\n\t\t\twarn((\"[DataService] Could not prepare data for %d: %s\"):format(userId, tostring(result)))\n\t\t\treleaseLockOnly(userId)\n\t\t\tstatus = \"error\"\n\t\tend\n\tend\n\n\tif data == nil then\n\t\tif RunService:IsStudio() then\n\t\t\twarn(\"[DataService] Studio fallback: using TEMPORARY data (not saved). Enable API Services + publish the place to test saving.\")\n\t\t\tdata = buildTemplate()\n\t\t\tdata.FirstJoin = os.time()\n\t\t\tephemeral = true\n\t\telse\n\t\t\tplayer:Kick(\"We couldn't load your save safely, so we stopped you from joining to protect your progress. Please rejoin in a minute.\")\n\t\t\twake(player, nil)\n\t\t\treturn\n\t\tend\n\tend\n\n\tlocal profile: Profile = {\n\t\tPlayer = player,\n\t\tUserId = userId,\n\t\tData = data,\n\t\tEphemeral = ephemeral,\n\t\tSaving = false,\n\t\tReleasing = false,\n\t}\n\tProfiles[player] = profile\n\twake(player, data)\n\tDataService.ProfileLoaded:Fire(player, data)\nend\n\nlocal function saveProfile(profile: Profile, releasing: boolean): boolean\n\tif profile.Ephemeral then\n\t\treturn true\n\tend\n\twhile profile.Saving do\n\t\ttask.wait()\n\tend\n\tprofile.Saving = true\n\tlocal ok, lostLock = writeRecord(profile.UserId, profile.Data, releasing)\n\tprofile.Saving = false\n\tif lostLock and not releasing and profile.Player.Parent then\n\t\tprofile.Player:Kick(\"Your session was opened on another server. Please rejoin.\")\n\tend\n\treturn ok\nend\n\nlocal function releaseProfile(player: Player)\n\tlocal profile = Profiles[player]\n\tif not profile then\n\t\twake(player, nil)\n\t\treturn\n\tend\n\tif profile.Releasing then\n\t\t-- another path (PlayerRemoving / BindToClose) is already saving; wait for it to finish\n\t\twhile Profiles[player] == profile do\n\t\t\ttask.wait()\n\t\tend\n\t\treturn\n\tend\n\tprofile.Releasing = true\n\tfor _, handler in ReleasingHandlers do\n\t\tlocal ok, err = pcall(handler, player, profile.Data)\n\t\tif not ok then\n\t\t\twarn(\"[DataService] Releasing handler error: \" .. tostring(err))\n\t\tend\n\tend\n\tprofile.Data.LastLogout = os.time()\n\tsaveProfile(profile, true)\n\tProfiles[player] = nil\nend\n\n---------------------------------------------------------------------\n-- Public API\n---------------------------------------------------------------------\n\nfunction DataService.GetData(player: Player): any\n\tlocal profile = Profiles[player]\n\treturn if profile and not profile.Releasing then profile.Data else nil\nend\n\n-- Yields until the player's data is loaded. Returns nil if they left or were kicked.\nfunction DataService.WaitForData(player: Player): any\n\tlocal existing = DataService.GetData(player)\n\tif existing then\n\t\treturn existing\n\tend\n\tif not player:IsDescendantOf(Players) then\n\t\treturn nil\n\tend\n\tlocal list = Waiters[player]\n\tif not list then\n\t\tlist = {}\n\t\tWaiters[player] = list\n\tend\n\ttable.insert(list, coroutine.running())\n\treturn coroutine.yield()\nend\n\nfunction DataService.IsEphemeral(player: Player): boolean\n\tlocal profile = Profiles[player]\n\treturn profile ~= nil and profile.Ephemeral\nend\n\n-- Register a callback that runs synchronously right before the final save (set timestamps, flush counters).\nfunction DataService.OnReleasing(handler: (Player, any) -> ())\n\ttable.insert(ReleasingHandlers, handler)\nend\n\n-- Immediate save, e.g. after a Robux purchase. Autosave handles everything else.\nfunction DataService.Save(player: Player): boolean\n\tlocal profile = Profiles[player]\n\tif not profile or profile.Releasing then\n\t\treturn false\n\tend\n\treturn saveProfile(profile, false)\nend\n\nfunction DataService.Init()\n\tPlayers.PlayerAdded:Connect(function(player)\n\t\ttask.spawn(onPlayerAdded, player)\n\tend)\n\tPlayers.PlayerRemoving:Connect(function(player)\n\t\treleaseProfile(player)\n\tend)\n\tfor _, player in Players:GetPlayers() do\n\t\ttask.spawn(onPlayerAdded, player)\n\tend\n\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(AUTOSAVE_INTERVAL)\n\t\t\tfor _, profile in Profiles do\n\t\t\t\tif not profile.Releasing and not profile.Saving then\n\t\t\t\t\ttask.spawn(saveProfile, profile, false)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\n\n\tgame:BindToClose(function()\n\t\tlocal pending = 0\n\t\tfor player in Profiles do\n\t\t\tpending += 1\n\t\t\ttask.spawn(function()\n\t\t\t\treleaseProfile(player)\n\t\t\t\tpending -= 1\n\t\t\tend)\n\t\tend\n\t\tlocal deadline = os.clock() + 25\n\t\twhile pending > 0 and os.clock() < deadline do\n\t\t\ttask.wait()\n\t\tend\n\tend)\nend\n\nreturn DataService\n"},
{"ServerScriptService/Services/EconomyService","ModuleScript","-- EconomyService (ModuleScript, server only). The ONLY place cash and XP are changed.\n-- Other services call AddCash / TrySpend / AddXP; nothing the client sends can reach these directly.\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal Signal = require(Shared.Utilities.Signal)\nlocal EconomyConfig = require(Shared.Config.EconomyConfig)\nlocal DataService = require(script.Parent.DataService)\nlocal StateService = require(script.Parent.StateService)\n\nlocal EconomyService = {}\nEconomyService.LevelUp = Signal.new() -- (player, newLevel)\n\n-- Per-server totals of where money enters (Sources) and leaves (Sinks); Phase 7 forwards these to analytics.\nEconomyService.Ledger = { Sources = {} :: { [string]: number }, Sinks = {} :: { [string]: number } }\n\nlocal function isValidAmount(amount: any): boolean\n\treturn type(amount) == \"number\" and amount == amount and amount >= 0 and amount < math.huge\nend\n\nfunction EconomyService.GetCash(player: Player): number\n\tlocal data = DataService.GetData(player)\n\treturn if data then data.Cash else 0\nend\n\n-- `source` is a short label (\"Sale\", \"QuestReward\", \"Debug\"...). Only business income should pass countAsEarnings = true,\n-- so lifetime earnings and leaderboards cannot be inflated by gifts.\nfunction EconomyService.AddCash(player: Player, amount: number, source: string, countAsEarnings: boolean?): boolean\n\tlocal data = DataService.GetData(player)\n\tif not data or not isValidAmount(amount) then\n\t\treturn false\n\tend\n\tamount = math.floor(amount)\n\tif amount <= 0 then\n\t\treturn false\n\tend\n\tdata.Cash = math.min(data.Cash + amount, EconomyConfig.MaxCash)\n\tif countAsEarnings then\n\t\tdata.Stats.LifetimeEarnings += amount\n\tend\n\tEconomyService.Ledger.Sources[source] = (EconomyService.Ledger.Sources[source] or 0) + amount\n\tStateService.Push(player, { Cash = data.Cash })\n\treturn true\nend\n\n-- Atomically checks and deducts. Returns false (and changes nothing) if the player can't afford it.\nfunction EconomyService.TrySpend(player: Player, amount: number, sink: string): boolean\n\tlocal data = DataService.GetData(player)\n\tif not data or not isValidAmount(amount) then\n\t\treturn false\n\tend\n\tamount = math.ceil(amount)\n\tif amount <= 0 or data.Cash < amount then\n\t\treturn false\n\tend\n\tdata.Cash -= amount\n\tdata.Stats.LifetimeSpent += amount\n\tEconomyService.Ledger.Sinks[sink] = (EconomyService.Ledger.Sinks[sink] or 0) + amount\n\tStateService.Push(player, { Cash = data.Cash })\n\treturn true\nend\n\nfunction EconomyService.AddXP(player: Player, amount: number, source: string): boolean\n\tlocal data = DataService.GetData(player)\n\tif not data or not isValidAmount(amount) then\n\t\treturn false\n\tend\n\tamount = math.floor(amount)\n\tif amount <= 0 then\n\t\treturn false\n\tend\n\tdata.XP += amount\n\tlocal leveled = false\n\twhile data.Level < EconomyConfig.XP.MaxLevel do\n\t\tlocal needed = EconomyConfig.XPToNextLevel(data.Level)\n\t\tif data.XP < needed then\n\t\t\tbreak\n\t\tend\n\t\tdata.XP -= needed\n\t\tdata.Level += 1\n\t\tleveled = true\n\tend\n\tif data.Level >= EconomyConfig.XP.MaxLevel then\n\t\tdata.XP = 0\n\tend\n\tStateService.Push(player, { XP = data.XP, Level = data.Level })\n\tif leveled then\n\t\tEconomyService.LevelUp:Fire(player, data.Level)\n\tend\n\treturn true\nend\n\nfunction EconomyService.GetStage(player: Player): number\n\tlocal data = DataService.GetData(player)\n\treturn if data then data.BusinessStage else 1\nend\n\nfunction EconomyService.Init()\n\tDataService.ProfileLoaded:Connect(function(_player, data)\n\t\tdata.Stats.Sessions += 1\n\tend)\nend\n\nreturn EconomyService\n"},
{"ServerScriptService/Services/PlotService","ModuleScript","-- PlotService (ModuleScript, server only)\n-- Assigns one plot per player, builds their business on it, moves their character there, frees the plot on leave.\n-- Server capacity is the number of plots; set Game Settings > Max Players to 6 so nobody is turned away.\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal Signal = require(Shared.Utilities.Signal)\nlocal DataService = require(script.Parent.DataService)\nlocal MapBuilder = require(script.Parent.Parent.Builders.MapBuilder)\nlocal StandBuilder = require(script.Parent.Parent.Builders.StandBuilder)\n\nlocal PlotService = {}\nPlotService.PlotAssigned = Signal.new() -- (player, plot)\n\ntype Plot = {\n\tIndex: number,\n\tModel: Model,\n\tBase: BasePart,\n\tOwner: Player?,\n\tAnchors: StandBuilder.Anchors?,\n}\n\nlocal plots: { Plot } = {}\nlocal byPlayer: { [Player]: Plot } = {}\n\nlocal function setOwnerSign(plot: Plot, text: string)\n\tlocal sign = plot.Model:FindFirstChild(\"OwnerSign\")\n\tlocal label = sign and sign:FindFirstChild(\"Text\", true)\n\tif label and label:IsA(\"TextLabel\") then\n\t\tlabel.Text = text\n\tend\nend\n\nlocal function moveCharacter(player: Player, plot: Plot)\n\tlocal character = player.Character\n\tif not character or not plot.Anchors then\n\t\treturn\n\tend\n\tif not character:FindFirstChild(\"HumanoidRootPart\") then\n\t\tcharacter:WaitForChild(\"HumanoidRootPart\", 5)\n\tend\n\t-- Let the engine finish placing a freshly spawned character at the SpawnLocation first,\n\t-- otherwise that placement can overwrite our move.\n\ttask.wait(0.1)\n\tif character.Parent and player.Character == character and plot.Anchors and character:FindFirstChild(\"HumanoidRootPart\") then\n\t\tcharacter:PivotTo(plot.Anchors.PlayerSpawn + Vector3.new(0, 4, 0))\n\tend\nend\n\nlocal function assign(player: Player, data: any)\n\tif byPlayer[player] or not player.Parent then\n\t\treturn\n\tend\n\tlocal plot: Plot? = nil\n\tfor _, candidate in plots do\n\t\tif not candidate.Owner then\n\t\t\tplot = candidate\n\t\t\tbreak\n\t\tend\n\tend\n\tif not plot then\n\t\tplayer:Kick(\"This server is full. Please join another one.\")\n\t\treturn\n\tend\n\n\tplot.Owner = player\n\tbyPlayer[player] = plot\n\tplot.Model:SetAttribute(\"OwnerUserId\", player.UserId)\n\n\tlocal name = if data.BusinessName ~= \"\" then data.BusinessName else (player.DisplayName .. \"'s Firework Stand\")\n\tplot.Anchors = StandBuilder.Build(plot.Model, plot.Base, data.BusinessStage, name)\n\tsetOwnerSign(plot, name)\n\n\ttask.spawn(moveCharacter, player, plot)\n\tPlotService.PlotAssigned:Fire(player, plot)\nend\n\nlocal function release(player: Player)\n\tlocal plot = byPlayer[player]\n\tif not plot then\n\t\treturn\n\tend\n\tbyPlayer[player] = nil\n\tplot.Owner = nil\n\tplot.Anchors = nil\n\tplot.Model:SetAttribute(\"OwnerUserId\", nil)\n\tlocal stand = plot.Model:FindFirstChild(\"Stand\")\n\tif stand then\n\t\tstand:Destroy()\n\tend\n\tsetOwnerSign(plot, \"FOR SALE\")\nend\n\nfunction PlotService.GetPlot(player: Player): Plot?\n\treturn byPlayer[player]\nend\n\nfunction PlotService.GetPlots(): { Plot }\n\treturn plots\nend\n\nfunction PlotService.Init()\n\tfor index, record in MapBuilder.Build() do\n\t\ttable.insert(plots, { Index = index, Model = record.Model, Base = record.Base, Owner = nil, Anchors = nil })\n\tend\n\n\tlocal function watchCharacter(player: Player)\n\t\tplayer.CharacterAdded:Connect(function()\n\t\t\tlocal plot = byPlayer[player]\n\t\t\tif plot then\n\t\t\t\ttask.spawn(moveCharacter, player, plot)\n\t\t\tend\n\t\tend)\n\tend\n\n\tPlayers.PlayerAdded:Connect(watchCharacter)\n\tfor _, player in Players:GetPlayers() do\n\t\twatchCharacter(player)\n\tend\n\n\tDataService.ProfileLoaded:Connect(assign)\n\tPlayers.PlayerRemoving:Connect(release)\nend\n\nreturn PlotService\n"},
{"ServerScriptService/Services/StateService","ModuleScript","-- StateService (ModuleScript, server only). Sends the small slice of player state the HUD needs.\n-- Server is authoritative; clients only ever receive state, never submit it.\n-- Changes are batched: many Push calls in one frame become a single remote.\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal RemoteRegistry = require(Shared.Utilities.RemoteRegistry)\nlocal Security = require(script.Parent.Parent.Security)\nlocal DataService = require(script.Parent.DataService)\n\nlocal StateService = {}\n\nlocal StateChanged: RemoteEvent\nlocal GetState: RemoteFunction\n\nlocal ready: { [Player]: boolean } = {}\nlocal pending: { [Player]: { [string]: any } } = {}\n\nlocal function snapshot(data)\n\treturn {\n\t\tCash = data.Cash,\n\t\tXP = data.XP,\n\t\tLevel = data.Level,\n\t\tBusinessStage = data.BusinessStage,\n\t\tBusinessName = data.BusinessName,\n\t}\nend\n\n-- changes: { Cash = 123, XP = 4, ... }. Ignored until the client has fetched its first snapshot\n-- (the snapshot already contains everything that happened before).\nfunction StateService.Push(player: Player, changes: { [string]: any })\n\tif not ready[player] then\n\t\treturn\n\tend\n\tlocal batch = pending[player]\n\tif not batch then\n\t\tbatch = {}\n\t\tpending[player] = batch\n\t\ttask.defer(function()\n\t\t\tpending[player] = nil\n\t\t\tif player.Parent then\n\t\t\t\tStateChanged:FireClient(player, batch)\n\t\t\tend\n\t\tend)\n\tend\n\tfor key, value in changes do\n\t\tbatch[key] = value\n\tend\nend\n\nfunction StateService.Init()\n\tStateChanged = RemoteRegistry.Event(\"StateChanged\")\n\tGetState = RemoteRegistry.Function(\"GetState\")\n\n\tGetState.OnServerInvoke = function(player: Player)\n\t\tif not Security.RateLimit(player, \"GetState\", 6, 10) then\n\t\t\treturn nil\n\t\tend\n\t\tlocal data = DataService.WaitForData(player)\n\t\tif not data then\n\t\t\treturn nil\n\t\tend\n\t\tready[player] = true\n\t\treturn snapshot(data)\n\tend\n\n\tPlayers.PlayerRemoving:Connect(function(player)\n\t\tready[player] = nil\n\t\tpending[player] = nil\n\tend)\nend\n\nreturn StateService\n"},
{"StarterPlayer/StarterPlayerScripts/ClientMain","LocalScript","-- ClientMain (LocalScript). Boots client controllers in order. Each controller is a ModuleScript with Init().\n\nlocal controllers = script.Parent:WaitForChild(\"Controllers\")\n\nlocal ORDER = {\n\t\"StateController\",\n\t\"UIController\",\n}\n\nfor _, name in ORDER do\n\tlocal ok, controller = pcall(require, controllers:WaitForChild(name))\n\tif not ok then\n\t\twarn((\"[ClientMain] Failed to load %s: %s\"):format(name, tostring(controller)))\n\telseif type(controller) == \"table\" and controller.Init then\n\t\tlocal initOk, err = pcall(controller.Init)\n\t\tif not initOk then\n\t\t\twarn((\"[ClientMain] %s.Init failed: %s\"):format(name, tostring(err)))\n\t\tend\n\tend\nend\n"},
{"StarterPlayer/StarterPlayerScripts/Controllers/StateController","ModuleScript","-- StateController (ModuleScript, client). Read-only mirror of the server's player state.\n-- The server is authoritative: this module never sends values to the server.\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal Signal = require(Shared.Utilities.Signal)\nlocal RemoteRegistry = require(Shared.Utilities.RemoteRegistry)\n\nlocal StateController = {}\nStateController.State = {} :: { [string]: any }\nStateController.Loaded = false\nStateController.Changed = Signal.new() -- (key, value)\nStateController.LoadedSignal = Signal.new() -- fires once, after the first snapshot\n\nlocal function apply(changes: { [string]: any })\n\tfor key, value in changes do\n\t\tStateController.State[key] = value\n\t\tStateController.Changed:Fire(key, value)\n\tend\nend\n\nfunction StateController.Init()\n\tlocal stateChanged = RemoteRegistry.Event(\"StateChanged\")\n\tlocal getState = RemoteRegistry.Function(\"GetState\")\n\n\tstateChanged.OnClientEvent:Connect(function(changes)\n\t\tif type(changes) == \"table\" then\n\t\t\tapply(changes)\n\t\tend\n\tend)\n\n\ttask.spawn(function()\n\t\tfor _ = 1, 6 do\n\t\t\tlocal ok, snapshot = pcall(function()\n\t\t\t\treturn getState:InvokeServer()\n\t\t\tend)\n\t\t\tif ok and type(snapshot) == \"table\" then\n\t\t\t\tapply(snapshot)\n\t\t\t\tStateController.Loaded = true\n\t\t\t\tStateController.LoadedSignal:Fire()\n\t\t\t\treturn\n\t\t\tend\n\t\t\ttask.wait(2)\n\t\tend\n\t\twarn(\"[StateController] Could not load player state from the server\")\n\tend)\nend\n\nreturn StateController\n"},
{"StarterPlayer/StarterPlayerScripts/Controllers/UIController","ModuleScript","-- UIController (ModuleScript, client). Builds the main HUD in code (no StarterGui assets needed).\n-- Layout is designed for 1280x720 and scaled with UIScale, so it fits phones, tablets, desktops and consoles.\n--   Top left: cash, business stage, XP bar      Left: menu buttons (placeholders until their phase)\n--   Right: restock timer / event / goal         Top centre: toast notifications\n\nlocal Players = game:GetService(\"Players\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal Format = require(Shared.Utilities.Format)\nlocal EconomyConfig = require(Shared.Config.EconomyConfig)\nlocal BuildingConfig = require(Shared.Config.BuildingConfig)\nlocal StateController = require(script.Parent.StateController)\n\nlocal UIController = {}\n\nlocal THEME = {\n\tPanel = Color3.fromRGB(28, 32, 48),\n\tPanelLight = Color3.fromRGB(44, 50, 74),\n\tStroke = Color3.fromRGB(255, 255, 255),\n\tText = Color3.fromRGB(240, 242, 250),\n\tMuted = Color3.fromRGB(160, 168, 190),\n\tCash = Color3.fromRGB(104, 230, 130),\n\tGain = Color3.fromRGB(210, 255, 220),\n\tLoss = Color3.fromRGB(255, 120, 120),\n\tXp = Color3.fromRGB(110, 170, 255),\n\tAccent = Color3.fromRGB(255, 196, 61),\n}\n\nlocal function make(className: string, props: { [string]: any }): any\n\tlocal instance = Instance.new(className)\n\tlocal parent = props.Parent\n\tfor key, value in props do\n\t\tif key ~= \"Parent\" then\n\t\t\tinstance[key] = value\n\t\tend\n\tend\n\tinstance.Parent = parent\n\treturn instance\nend\n\nlocal function round(parent: Instance, radius: number)\n\tmake(\"UICorner\", { CornerRadius = UDim.new(0, radius), Parent = parent })\nend\n\nlocal function outline(parent: Instance, transparency: number)\n\tmake(\"UIStroke\", { Color = THEME.Stroke, Transparency = transparency, Thickness = 1.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = parent })\nend\n\nlocal function text(parent: Instance, props: { [string]: any }): TextLabel\n\tprops.Parent = parent\n\tprops.BackgroundTransparency = 1\n\tprops.TextColor3 = props.TextColor3 or THEME.Text\n\tprops.Font = props.Font or Enum.Font.GothamMedium\n\treturn make(\"TextLabel\", props)\nend\n\nlocal gui: ScreenGui\nlocal toastHolder: Frame\nlocal cashLabel: TextLabel\nlocal stageLabel: TextLabel\nlocal xpFill: Frame\nlocal xpLabel: TextLabel\nlocal cashValue: NumberValue\n\n---------------------------------------------------------------------\n-- Toasts\n---------------------------------------------------------------------\n\nfunction UIController.Toast(message: string, color: Color3?)\n\tlocal toast = make(\"Frame\", {\n\t\tSize = UDim2.fromOffset(340, 44),\n\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\tPosition = UDim2.new(0.5, 0, 0, -60),\n\t\tBackgroundColor3 = THEME.Panel,\n\t\tParent = toastHolder,\n\t})\n\tround(toast, 12)\n\tlocal stroke = make(\"UIStroke\", { Color = color or THEME.Accent, Thickness = 2, Parent = toast })\n\ttext(toast, {\n\t\tSize = UDim2.fromScale(1, 1),\n\t\tText = message,\n\t\tTextSize = 16,\n\t\tTextWrapped = true,\n\t\tFont = Enum.Font.GothamBold,\n\t})\n\tlocal slideIn = TweenService:Create(toast, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Position = UDim2.new(0.5, 0, 0, 8) })\n\tslideIn:Play()\n\ttask.delay(2.6, function()\n\t\tlocal slideOut = TweenService:Create(toast, TweenInfo.new(0.25), { Position = UDim2.new(0.5, 0, 0, -60) })\n\t\tslideOut:Play()\n\t\tslideOut.Completed:Wait()\n\t\tstroke:Destroy()\n\t\ttoast:Destroy()\n\tend)\nend\n\n---------------------------------------------------------------------\n-- HUD pieces\n---------------------------------------------------------------------\n\nlocal function buildTopLeft()\n\tlocal panel = make(\"Frame\", {\n\t\tName = \"StatusPanel\",\n\t\tPosition = UDim2.fromOffset(12, 8),\n\t\tSize = UDim2.fromOffset(290, 100),\n\t\tBackgroundColor3 = THEME.Panel,\n\t\tParent = gui,\n\t})\n\tround(panel, 14)\n\toutline(panel, 0.8)\n\n\tcashLabel = text(panel, {\n\t\tName = \"Cash\",\n\t\tPosition = UDim2.fromOffset(14, 6),\n\t\tSize = UDim2.fromOffset(262, 42),\n\t\tText = \"$0\",\n\t\tTextSize = 36,\n\t\tTextColor3 = THEME.Cash,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tFont = Enum.Font.FredokaOne,\n\t})\n\n\tstageLabel = text(panel, {\n\t\tName = \"Stage\",\n\t\tPosition = UDim2.fromOffset(14, 50),\n\t\tSize = UDim2.fromOffset(262, 18),\n\t\tText = \"\",\n\t\tTextSize = 14,\n\t\tTextColor3 = THEME.Muted,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t})\n\n\tlocal barBack = make(\"Frame\", {\n\t\tName = \"XPBar\",\n\t\tPosition = UDim2.fromOffset(14, 74),\n\t\tSize = UDim2.fromOffset(262, 16),\n\t\tBackgroundColor3 = THEME.PanelLight,\n\t\tParent = panel,\n\t})\n\tround(barBack, 8)\n\txpFill = make(\"Frame\", {\n\t\tName = \"Fill\",\n\t\tSize = UDim2.fromScale(0, 1),\n\t\tBackgroundColor3 = THEME.Xp,\n\t\tParent = barBack,\n\t})\n\tround(xpFill, 8)\n\txpLabel = text(barBack, {\n\t\tName = \"Label\",\n\t\tSize = UDim2.fromScale(1, 1),\n\t\tText = \"\",\n\t\tTextSize = 11,\n\t\tFont = Enum.Font.GothamBold,\n\t\tZIndex = 2,\n\t})\nend\n\nlocal MENU = {\n\t{ Icon = \"\240\159\155\146\", Name = \"Shop\", Phase = 2 },\n\t{ Icon = \"\240\159\147\166\", Name = \"Inventory\", Phase = 2 },\n\t{ Icon = \"\240\159\147\150\", Name = \"Collection\", Phase = 3 },\n\t{ Icon = \"\240\159\145\183\", Name = \"Employees\", Phase = 4 },\n\t{ Icon = \"\240\159\147\156\", Name = \"Quests\", Phase = 5 },\n}\n\nlocal function buildLeftMenu()\n\tlocal holder = make(\"Frame\", {\n\t\tName = \"Menu\",\n\t\tAnchorPoint = Vector2.new(0, 0.5),\n\t\tPosition = UDim2.new(0, 12, 0.5, 20),\n\t\tSize = UDim2.fromOffset(66, #MENU * 62),\n\t\tBackgroundTransparency = 1,\n\t\tParent = gui,\n\t})\n\tmake(\"UIListLayout\", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = holder })\n\n\tfor index, entry in MENU do\n\t\tlocal button = make(\"TextButton\", {\n\t\t\tName = entry.Name,\n\t\t\tLayoutOrder = index,\n\t\t\tSize = UDim2.fromOffset(66, 56),\n\t\t\tBackgroundColor3 = THEME.Panel,\n\t\t\tAutoButtonColor = true,\n\t\t\tText = entry.Icon .. \"\\n\" .. entry.Name,\n\t\t\tTextSize = 12,\n\t\t\tTextColor3 = THEME.Text,\n\t\t\tFont = Enum.Font.GothamBold,\n\t\t\tParent = holder,\n\t\t})\n\t\tround(button, 12)\n\t\toutline(button, 0.85)\n\t\tbutton.Activated:Connect(function()\n\t\t\tUIController.Toast(entry.Name .. \" opens in Phase \" .. entry.Phase, THEME.Muted)\n\t\tend)\n\tend\nend\n\nlocal function buildRightPanel()\n\tlocal panel = make(\"Frame\", {\n\t\tName = \"InfoPanel\",\n\t\tAnchorPoint = Vector2.new(1, 0),\n\t\tPosition = UDim2.new(1, -12, 0, 8),\n\t\tSize = UDim2.fromOffset(250, 150),\n\t\tBackgroundColor3 = THEME.Panel,\n\t\tParent = gui,\n\t})\n\tround(panel, 14)\n\toutline(panel, 0.8)\n\tmake(\"UIPadding\", { PaddingTop = UDim.new(0, 10), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12), PaddingBottom = UDim.new(0, 10), Parent = panel })\n\tmake(\"UIListLayout\", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = panel })\n\n\tlocal function row(order: number, title: string, body: string, height: number)\n\t\tlocal container = make(\"Frame\", { LayoutOrder = order, Size = UDim2.new(1, 0, 0, height), BackgroundTransparency = 1, Parent = panel })\n\t\ttext(container, { Size = UDim2.new(1, 0, 0, 14), Text = title, TextSize = 11, TextColor3 = THEME.Muted, TextXAlignment = Enum.TextXAlignment.Left, Font = Enum.Font.GothamBold })\n\t\ttext(container, { Position = UDim2.fromOffset(0, 14), Size = UDim2.new(1, 0, 1, -14), Text = body, TextSize = 14, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top })\n\tend\n\n\trow(1, \"SUPPLIER RESTOCK\", \"--:--  (Phase 2)\", 34)\n\trow(2, \"ACTIVE EVENT\", \"None  (Phase 5)\", 34)\n\trow(3, \"CURRENT GOAL\", \"Foundation complete. Ordering inventory arrives in Phase 2.\", 52)\nend\n\n---------------------------------------------------------------------\n-- State -> HUD\n---------------------------------------------------------------------\n\nlocal function refreshStage()\n\tlocal state = StateController.State\n\tlocal stage = BuildingConfig.Get(state.BusinessStage or 1)\n\tstageLabel.Text = (\"Business Lv %d  \194\183  %s\"):format(stage.Level, stage.Name)\nend\n\nlocal function refreshXP()\n\tlocal state = StateController.State\n\tlocal level = state.Level or 1\n\tlocal needed = EconomyConfig.XPToNextLevel(level)\n\tlocal xp = state.XP or 0\n\tlocal fraction = if level >= EconomyConfig.XP.MaxLevel then 1 else math.clamp(xp / needed, 0, 1)\n\tTweenService:Create(xpFill, TweenInfo.new(0.3, Enum.EasingStyle.Quad), { Size = UDim2.fromScale(fraction, 1) }):Play()\n\txpLabel.Text = if level >= EconomyConfig.XP.MaxLevel then (\"Lv %d  MAX\"):format(level) else (\"Lv %d  \194\183  %s / %s XP\"):format(level, Format.Commas(xp), Format.Commas(needed))\nend\n\nlocal function setCash(newCash: number, animate: boolean)\n\tlocal previous = cashValue.Value\n\tif not animate then\n\t\tcashValue.Value = newCash\n\t\treturn\n\tend\n\tTweenService:Create(cashValue, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Value = newCash }):Play()\n\tcashLabel.TextColor3 = if newCash >= previous then THEME.Gain else THEME.Loss\n\tTweenService:Create(cashLabel, TweenInfo.new(0.6), { TextColor3 = THEME.Cash }):Play()\nend\n\nlocal previousLevel: number? = nil\n\nlocal function onStateChanged(key: string, value: any)\n\tif key == \"Cash\" then\n\t\tsetCash(value, StateController.Loaded)\n\telseif key == \"XP\" then\n\t\trefreshXP()\n\telseif key == \"Level\" then\n\t\trefreshXP()\n\t\tif previousLevel and value > previousLevel then\n\t\t\tUIController.Toast(\"Level up! You reached level \" .. value, THEME.Accent)\n\t\tend\n\t\tpreviousLevel = value\n\telseif key == \"BusinessStage\" then\n\t\trefreshStage()\n\tend\nend\n\n---------------------------------------------------------------------\n-- Init\n---------------------------------------------------------------------\n\nfunction UIController.Init()\n\tlocal playerGui = Players.LocalPlayer:WaitForChild(\"PlayerGui\")\n\n\tgui = make(\"ScreenGui\", {\n\t\tName = \"MainHUD\",\n\t\tResetOnSpawn = false,\n\t\tIgnoreGuiInset = false,\n\t\tZIndexBehavior = Enum.ZIndexBehavior.Sibling,\n\t\tParent = playerGui,\n\t})\n\n\tlocal uiScale = make(\"UIScale\", { Parent = gui })\n\tlocal function updateScale()\n\t\tlocal camera = Workspace.CurrentCamera\n\t\tif not camera then\n\t\t\treturn\n\t\tend\n\t\tlocal viewport = camera.ViewportSize\n\t\tuiScale.Scale = math.clamp(math.min(viewport.X / 1280, viewport.Y / 720), 0.55, 1.25)\n\tend\n\tupdateScale()\n\tif Workspace.CurrentCamera then\n\t\tWorkspace.CurrentCamera:GetPropertyChangedSignal(\"ViewportSize\"):Connect(updateScale)\n\tend\n\n\ttoastHolder = make(\"Frame\", { Name = \"Toasts\", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 10, Parent = gui })\n\n\tcashValue = Instance.new(\"NumberValue\")\n\tcashValue.Changed:Connect(function(value)\n\t\tcashLabel.Text = Format.Money(value)\n\tend)\n\n\tbuildTopLeft()\n\tbuildLeftMenu()\n\tbuildRightPanel()\n\n\tStateController.Changed:Connect(onStateChanged)\n\tStateController.LoadedSignal:Connect(function()\n\t\tlocal state = StateController.State\n\t\tpreviousLevel = state.Level\n\t\tsetCash(state.Cash or 0, false)\n\t\trefreshStage()\n\t\trefreshXP()\n\t\tUIController.Toast(\"Welcome to your new firework business!\", THEME.Accent)\n\tend)\n\tif StateController.Loaded then\n\t\tlocal state = StateController.State\n\t\tpreviousLevel = state.Level\n\t\tsetCash(state.Cash or 0, false)\n\t\trefreshStage()\n\t\trefreshXP()\n\telse\n\t\tcashLabel.Text = \"$0\"\n\tend\nend\n\nreturn UIController\n"},
}
local FOLDERS = {"ReplicatedStorage/Remotes","ReplicatedStorage/Assets","ServerStorage/BuildingModels","ServerStorage/FireworkModels","ServerStorage/CustomerModels","ServerStorage/EmployeeModels","ServerStorage/DeliveryModels"}
local function split(path) local parts = {} for part in string.gmatch(path, "[^/]+") do table.insert(parts, part) end return parts end
local function ensureFolderPath(parts, upTo) local node = game:GetService(parts[1]) for i = 2, upTo do local child = node:FindFirstChild(parts[i]) if not child then child = Instance.new("Folder") child.Name = parts[i] child.Parent = node end node = child end return node end
local recording = game:GetService("ChangeHistoryService"):TryBeginRecording("Install Run a Firework Stand Phase 1")
local installed = 0
for _, path in ipairs(FOLDERS) do ensureFolderPath(split(path), #split(path)) end
for _, entry in ipairs(FILES) do
local parts = split(entry[1])
local parent = ensureFolderPath(parts, #parts - 1)
local name = parts[#parts]
local existing = parent:FindFirstChild(name)
if existing and existing.ClassName ~= entry[2] then existing:Destroy() existing = nil end
local script = existing or Instance.new(entry[2])
script.Name = name
script.Source = entry[3]
script.Parent = parent
installed += 1
end
if recording then game:GetService("ChangeHistoryService"):FinishRecording(recording, Enum.FinishRecordingOperation.Commit) end
print("[Installer] Installed or updated " .. installed .. " scripts. Run a Firework Stand Phase 1 is ready.")
